// HasClient applies the HasEdge predicate on the "client" edge.
func HasClient() predicate.SPVConnection {
	return predicate.SPVConnection(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ClientTable, ClientColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasClientWith applies the HasEdge predicate on the "client" edge with a given conditions (other predicates).
func HasClientWith(preds ...predicate.AccountingClient) predicate.SPVConnection {
	return predicate.SPVConnection(func(s *sql.Selector) {
		step := newClientStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasSourceDocuments applies the HasEdge predicate on the "source_documents" edge.
func HasSourceDocuments() predicate.SPVConnection {
	return predicate.SPVConnection(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, SourceDocumentsTable, SourceDocumentsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSourceDocumentsWith applies the HasEdge predicate on the "source_documents" edge with a given conditions (other predicates).
func HasSourceDocumentsWith(preds ...predicate.SPVSourceDocument) predicate.SPVConnection {
	return predicate.SPVConnection(func(s *sql.Selector) {
		step := newSourceDocumentsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SPVConnection) predicate.SPVConnection {
	return predicate.SPVConnection(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SPVConnection) predicate.SPVConnection {
	return predicate.SPVConnection(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SPVConnection) predicate.SPVConnection {
	return predicate.SPVConnection(sql.NotPredicates(p))
}
